        const bool standIn = CampaignStandIn("mills_bomb") != nullptr;
        ctx.r3.u64 = names + (standIn ? 32 : 0);
        static int said = 0;
        if ((said < 10 && said++ < 10)) { printf("bots: kit grenades: %s\n", standIn ? "Mills bombs not on this map: frags" : "Mills bombs"); fflush(stdout); }
